import{_ as a,c as e,o as i,a4 as o}from"./chunks/framework.4aTu-Nia.js";const f=JSON.parse('{"title":"VIM-ISSUES","description":"","frontmatter":{},"headers":[],"relativePath":"tools/vim-issues.md","filePath":"tools/vim-issues.md"}'),l={name:"tools/vim-issues.md"},s=o(`<h1 id="vim-issues" tabindex="-1">VIM-ISSUES <a class="header-anchor" href="#vim-issues" aria-label="Permalink to &quot;VIM-ISSUES&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#ssh-上复制">ssh 上复制</a></li><li><a href="#python-支持">python 支持</a></li><li><a href="#set-commit-editor">set commit editor</a></li><li><a href="#编码转换-不同系统间的文件-常意外报错">编码转换，不同系统间的文件，常意外报错</a></li><li><a href="#提示恢复时-删除交换文件">提示恢复时，删除交换文件</a></li><li><a href="#与系统剪贴板交互">与系统剪贴板交互</a></li><li><a href="#输入法切换">输入法切换</a></li><li><a href="#不使用当前配置启动-标准-vim">不使用当前配置启动(标准 vim)</a></li><li><a href="#缓冲区-buffers-对应浏览器中的标签页">缓冲区 buffers （对应浏览器中的标签页）</a></li><li><a href="#忽略已记录文件">忽略已记录文件</a></li><li><a href="#viminfo-缺少对应的-in-line">viminfo: 缺少对应的 &#39;&gt;&#39; in line:</a></li><li><a href="#缩进不一致">缩进不一致</a></li><li><a href="#缩进指导">缩进指导</a></li><li><a href="#重载当前文件">重载当前文件</a></li><li><a href="#移除换行无用字符-m">移除换行无用字符^m</a></li><li><a href="#提示不能修改-cannot-make-changes-modifiable-is-off">提示不能修改 Cannot make changes, &#39;Modifiable&#39; is off</a></li><li><a href="#查看当前文件路径">查看当前文件路径</a></li><li><a href="#批量替换">批量替换</a></li><li><a href="#nodejs-调试">nodejs 调试</a></li><li><a href="#vim-vue-插件卡顿">vim-vue 插件卡顿</a><ul><li><a href="#如何分析语法时间开销">如何分析语法时间开销</a></li></ul></li><li><a href="#只能运行-zsh-非交互命令">只能运行 zsh 非交互命令</a></li><li><a href="#项目配置">项目配置</a></li><li><a href="#color-theme">color theme</a></li><li><a href="#用-vim-编辑-markdown-时直接粘贴图片-知乎">用 Vim 编辑 Markdown 时直接粘贴图片 - 知乎</a></li><li><a href="#模式">模式</a></li><li><a href="#不保存退出">不保存退出</a></li><li><a href="#替换转义">替换转义</a></li></ul></nav><h2 id="ssh-上复制" tabindex="-1">ssh 上复制 <a class="header-anchor" href="#ssh-上复制" aria-label="Permalink to &quot;ssh 上复制&quot;">​</a></h2><p>无法与图形端系统交互 cat / less 打印到终端 不过，用本地 vim 编辑更好？</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scp://remoteuser@server.tld//path/to/document</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scp://oaker@vserver.oaker.bid:29979//home/oaker/tmp.js</span></span></code></pre></div><h2 id="python-支持" tabindex="-1">python 支持 <a class="header-anchor" href="#python-支持" aria-label="Permalink to &quot;python 支持&quot;">​</a></h2><p>安装 vim-nox</p><h2 id="set-commit-editor" tabindex="-1">set commit editor <a class="header-anchor" href="#set-commit-editor" aria-label="Permalink to &quot;set commit editor&quot;">​</a></h2><p><code>$ git config core.editor &quot;vim&quot;</code></p><h2 id="编码转换-不同系统间的文件-常意外报错" tabindex="-1">编码转换，不同系统间的文件，常意外报错 <a class="header-anchor" href="#编码转换-不同系统间的文件-常意外报错" aria-label="Permalink to &quot;编码转换，不同系统间的文件，常意外报错&quot;">​</a></h2><p><code>:w ++ff=unix</code></p><h2 id="提示恢复时-删除交换文件" tabindex="-1">提示恢复时，删除交换文件 <a class="header-anchor" href="#提示恢复时-删除交换文件" aria-label="Permalink to &quot;提示恢复时，删除交换文件&quot;">​</a></h2><p>可能是在别的地方也在打开，关闭只留一个 复制给出的路径，<code>rm</code></p><h2 id="与系统剪贴板交互" tabindex="-1">与系统剪贴板交互 <a class="header-anchor" href="#与系统剪贴板交互" aria-label="Permalink to &quot;与系统剪贴板交互&quot;">​</a></h2><p>查看是否支持 <code>$ vim --version | grep clipboard</code> +号表示支持，-号相反 如果不支持，安装 <code>$ sudo apt-get install vim-gnome</code></p><h2 id="输入法切换" tabindex="-1">输入法切换 <a class="header-anchor" href="#输入法切换" aria-label="Permalink to &quot;输入法切换&quot;">​</a></h2><p>中文模式编辑完成后，<code>shift - esc or jk</code> 英文模式编辑完成后，<code>esc or jk</code></p><h2 id="不使用当前配置启动-标准-vim" tabindex="-1">不使用当前配置启动(标准 vim) <a class="header-anchor" href="#不使用当前配置启动-标准-vim" aria-label="Permalink to &quot;不使用当前配置启动(标准 vim)&quot;">​</a></h2><p><code>$ vim -u none -n</code></p><p><code>&lt;cr&gt;</code>指的是回车，不是<code>&lt;c-r&gt;</code><code>cw .</code> 有时比正则要快 cgn s/foo/bar/g s/foo/bar/gc (confirm before replace) d} 删除直到空行</p><h2 id="缓冲区-buffers-对应浏览器中的标签页" tabindex="-1">缓冲区 buffers （对应浏览器中的标签页） <a class="header-anchor" href="#缓冲区-buffers-对应浏览器中的标签页" aria-label="Permalink to &quot;缓冲区 buffers （对应浏览器中的标签页）&quot;">​</a></h2><ul><li><code>:ls</code> 列出缓冲区文件列表</li><li><code>:b keyword&lt;TAB&gt;</code> 关键字 tab 补全/或编号，快速定位打开缓冲区中的文件</li><li><code>:sb keyword&lt;TAB&gt;</code> 分屏打开文件，保持了固定顺序，也可<code>sbfirst</code></li><li><code>bn/bp</code> 上一个/下一个</li><li><code>&lt;C-^&gt;\`\`:e #</code> 来回切换，然后切换回原目录<code>:cd -</code></li><li><code>leader cd</code> 切换工作目录为当前文件所在目录</li><li><code>:b some-unique-part-of-the-file-path</code> 在文件间快速跳转</li></ul><h2 id="忽略已记录文件" tabindex="-1">忽略已记录文件 <a class="header-anchor" href="#忽略已记录文件" aria-label="Permalink to &quot;忽略已记录文件&quot;">​</a></h2><p><code>$ git update-index --assume-unchanged &lt;path&gt;</code> 重置 <code>$ git update-index --no-assume-unchanged</code></p><h2 id="viminfo-缺少对应的-in-line" tabindex="-1">viminfo: 缺少对应的 &#39;&gt;&#39; in line: <a class="header-anchor" href="#viminfo-缺少对应的-in-line" aria-label="Permalink to &quot;viminfo: 缺少对应的 &#39;&gt;&#39; in line:&quot;">​</a></h2><pre><code>rm ~/.viminfo
</code></pre><h2 id="缩进不一致" tabindex="-1">缩进不一致 <a class="header-anchor" href="#缩进不一致" aria-label="Permalink to &quot;缩进不一致&quot;">​</a></h2><p>在不同环境，tab 制表键设置不同，导致显示差异 统一转换成空格，expandtab 输入 tab，<code>ctrl-v&lt;tab&gt;</code> 当前文件转换，:retab <a href="http://vim.wikia.com/wiki/converting_tabs_to_spaces" target="_blank" rel="noreferrer">converting tabs to spaces | vim tips wiki | fandom powered by wikia</a></p><h2 id="缩进指导" tabindex="-1">缩进指导 <a class="header-anchor" href="#缩进指导" aria-label="Permalink to &quot;缩进指导&quot;">​</a></h2><ul><li>水平缩进显示 <code>:set list</code>，大短杠为 Tab，小短杠为空格，</li><li>垂直对齐显示 <code>&lt;leader&gt; il</code></li></ul><h2 id="重载当前文件" tabindex="-1">重载当前文件 <a class="header-anchor" href="#重载当前文件" aria-label="Permalink to &quot;重载当前文件&quot;">​</a></h2><p><code>:e</code></p><h2 id="移除换行无用字符-m" tabindex="-1">移除换行无用字符^m <a class="header-anchor" href="#移除换行无用字符-m" aria-label="Permalink to &quot;移除换行无用字符^m&quot;">​</a></h2><p><code>:%s/\\r$//g</code></p><h2 id="提示不能修改-cannot-make-changes-modifiable-is-off" tabindex="-1">提示不能修改 Cannot make changes, &#39;Modifiable&#39; is off <a class="header-anchor" href="#提示不能修改-cannot-make-changes-modifiable-is-off" aria-label="Permalink to &quot;提示不能修改 Cannot make changes, &#39;Modifiable&#39; is off&quot;">​</a></h2><p>set ma (modifiable) / set noma</p><h2 id="查看当前文件路径" tabindex="-1">查看当前文件路径 <a class="header-anchor" href="#查看当前文件路径" aria-label="Permalink to &quot;查看当前文件路径&quot;">​</a></h2><p><code>echo @%</code></p><h2 id="批量替换" tabindex="-1">批量替换 <a class="header-anchor" href="#批量替换" aria-label="Permalink to &quot;批量替换&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>:arg *.cpp	All *.cpp files in current directory.</span></span>
<span class="line"><span>:argadd *.h	And all *.h files.</span></span>
<span class="line"><span>:arg	Optional: Display the current arglist.</span></span>
<span class="line"><span>:argdo %s/pattern/replace/ge | update	Search and replace in all files in arglist.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:argadd **/*.h	All *.h files in and below current directory</span></span></code></pre></div><h2 id="nodejs-调试" tabindex="-1">nodejs 调试 <a class="header-anchor" href="#nodejs-调试" aria-label="Permalink to &quot;nodejs 调试&quot;">​</a></h2><ol><li><code>&lt;leader&gt;e</code> 执行 AsyncRun</li><li><code>:cw</code> 打开 QuickFix 窗口</li></ol><h2 id="vim-vue-插件卡顿" tabindex="-1">vim-vue 插件卡顿 <a class="header-anchor" href="#vim-vue-插件卡顿" aria-label="Permalink to &quot;vim-vue 插件卡顿&quot;">​</a></h2><p>原因分析：并不仅仅是多语言语法高亮问题导致 <a href="https://github.com/posva/vim-vue/issues/95#issuecomment-374108025" target="_blank" rel="noreferrer">I can&#39;t fix the slowness. · Issue #95 · posva/vim-vue</a></p><ul><li>关闭相对行数 <code>set nornu</code></li><li>使用 vim-vue 性能优化分支</li></ul><h3 id="如何分析语法时间开销" tabindex="-1">如何分析语法时间开销 <a class="header-anchor" href="#如何分析语法时间开销" aria-label="Permalink to &quot;如何分析语法时间开销&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>:syntime on</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:syntime report</span></span>
<span class="line"><span></span></span>
<span class="line"><span>then remove the offending patterns</span></span></code></pre></div><h2 id="只能运行-zsh-非交互命令" tabindex="-1">只能运行 zsh 非交互命令 <a class="header-anchor" href="#只能运行-zsh-非交互命令" aria-label="Permalink to &quot;只能运行 zsh 非交互命令&quot;">​</a></h2><p>比如 alias.sh 中的运行不了</p><p><a href="https://vi.stackexchange.com/questions/16186/how-to-run-zsh-aliased-command-from-vim-command-mode/16197" target="_blank" rel="noreferrer">How to run zsh aliased command from vim command mode? - Vi and Vim Stack Exchange</a></p><h2 id="项目配置" tabindex="-1">项目配置 <a class="header-anchor" href="#项目配置" aria-label="Permalink to &quot;项目配置&quot;">​</a></h2><p><code>set exrc</code> 在项目根目录，创建<code>.exrc</code>，使用这个文件名可兼容 vim 和 nvim</p><h2 id="color-theme" tabindex="-1">color theme <a class="header-anchor" href="#color-theme" aria-label="Permalink to &quot;color theme&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>&quot; Plug &#39;joshdick/onedark.vim&#39; &quot; only dark</span></span>
<span class="line"><span>&quot; Plug &#39;tomasiser/vim-code-dark&#39; &quot; like vscode dark</span></span>
<span class="line"><span>&quot; Plug &#39;rakr/vim-one&#39; &quot; not work?</span></span></code></pre></div><p><a href="http://www.calmar.ws/vim/256-xterm-24bit-rgb-color-chart.html" target="_blank" rel="noreferrer">256 Terminal colors and their 24bit equivalent (or similar)</a><a href="https://github.com/NLKNguyen/papercolor-theme/blob/master/colors/PaperColor.vim" target="_blank" rel="noreferrer">papercolor-theme/PaperColor.vim at master · NLKNguyen/papercolor-theme</a></p><h2 id="用-vim-编辑-markdown-时直接粘贴图片-知乎" tabindex="-1"><a href="https://zhuanlan.zhihu.com/p/138060559" target="_blank" rel="noreferrer">用 Vim 编辑 Markdown 时直接粘贴图片 - 知乎</a> <a class="header-anchor" href="#用-vim-编辑-markdown-时直接粘贴图片-知乎" aria-label="Permalink to &quot;[用 Vim 编辑 Markdown 时直接粘贴图片 - 知乎](https://zhuanlan.zhihu.com/p/138060559)&quot;">​</a></h2><h2 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to &quot;模式&quot;">​</a></h2><ul><li>多用 buffers，替代 Tab/Window</li></ul><h2 id="不保存退出" tabindex="-1">不保存退出 <a class="header-anchor" href="#不保存退出" aria-label="Permalink to &quot;不保存退出&quot;">​</a></h2><ol><li>按键太难记</li><li>kill tmux window，reopen</li></ol><h2 id="替换转义" tabindex="-1">替换转义 <a class="header-anchor" href="#替换转义" aria-label="Permalink to &quot;替换转义&quot;">​</a></h2><p>用 # 代替 / 这样避免路径中的 / 需要转义</p>`,62),t=[s];function r(n,h,c,d,p,m){return i(),e("div",null,t)}const b=a(l,[["render",r]]);export{f as __pageData,b as default};
